{
  "_note": "Fictional product, made up for a demo. Every figure a page shows must come from this file.",
  "product": "Tideline",
  "what": "Uptime and cron-job monitoring for small engineering teams",
  "audience": {
    "text": "Teams of 2 to 20 engineers who run their own services",
    "team_size_min": 2,
    "team_size_max": 20
  },
  "how": {
    "check_interval_seconds": 30,
    "regions": 6,
    "regions_that_must_agree": 2,
    "alert_channels": [
      "Slack",
      "email",
      "SMS",
      "PagerDuty",
      "webhooks"
    ]
  },
  "cron_monitoring": "Each job pings a unique URL when it finishes; a missed ping alerts after a grace period you set",
  "status_pages": "One public status page per project, on your own domain",
  "setup": {
    "text": "Paste a URL. The first check runs within 60 seconds.",
    "first_check_within_seconds": 60
  },
  "pricing": {
    "free": {
      "price_usd_per_month": 0,
      "monitors": 5
    },
    "team": {
      "price_usd_per_month": 19,
      "monitors": 100
    }
  },
  "trial": {
    "days": 14,
    "card_required": false
  },
  "beta": {
    "since": "March 2026",
    "teams": 412
  },
  "customer_quotes": []
}

content.content:
1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tideline — Uptime monitoring for small engineering teams</title>
7	<meta name="description" content="Tideline watches your APIs, websites, and cron jobs from 12 regions every 30 seconds — and only wakes you up when it's real.">
8	<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='8' fill='%230b1530'/%3E%3Cpath d='M5 19c3.5 0 3.5-4 7-4s3.5 4 7 4 3.5-4 7-4' stroke='%2322e5c8' stroke-width='3' fill='none' stroke-linecap='round'/%3E%3C/svg%3E">
9	<style>
10	:root{
11	  --bg:#050b1a;
12	  --bg-2:#081229;
13	  --surface:rgba(255,255,255,.035);
14	  --surface-2:rgba(255,255,255,.06);
15	  --border:rgba(148,178,255,.12);
16	  --border-2:rgba(148,178,255,.22);
17	  --text:#e9efff;
18	  --muted:#9aa7c7;
19	  --dim:#6b789a;
20	  --teal:#22e5c8;
21	  --cyan:#38bdf8;
22	  --violet:#8b5cf6;
23	  --coral:#ff6b6b;
24	  --amber:#fbbf24;
25	  --green:#34d399;
26	  --grad:linear-gradient(100deg,#22e5c8 0%,#38bdf8 45%,#8b5cf6 100%);
27	  --radius:18px;
28	  --shadow:0 30px 80px -20px rgba(0,0,0,.6),0 0 0 1px var(--border);
29	  --font:ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",Inter,Roboto,"Helvetica Neue",Arial,sans-serif;
30	  --mono:ui-monospace,SFMono-Regular,"SF Mono",Menlo,Consolas,"Liberation Mono",monospace;
31	}
32	*{box-sizing:border-box;margin:0;padding:0}
33	html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
34	body{
35	  font-family:var(--font);background:var(--bg);color:var(--text);
36	  line-height:1.6;overflow-x:hidden;-webkit-font-smoothing:antialiased;
37	}
38	a{color:inherit;text-decoration:none}
39	button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}
40	img,svg{display:block}
41	.wrap{max-width:1180px;margin:0 auto;padding:0 24px}
42	::selection{background:rgba(34,229,200,.35)}
43	:focus-visible{outline:2px solid var(--teal);outline-offset:3px;border-radius:8px}
44	
45	/* ---------- Background ---------- */
46	.bg-fx{position:fixed;inset:0;z-index:-1;pointer-events:none;overflow:hidden}
47	.bg-fx::before{
48	  content:"";position:absolute;inset:0;
49	  background-image:linear-gradient(rgba(148,178,255,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(148,178,255,.05) 1px,transparent 1px);
50	  background-size:56px 56px;
51	  mask-image:radial-gradient(ellipse 80% 60% at 50% 0%,#000 30%,transparent 75%);
52	  -webkit-mask-image:radial-gradient(ellipse 80% 60% at 50% 0%,#000 30%,transparent 75%);
53	}
54	.orb{position:absolute;border-radius:50%;filter:blur(90px);opacity:.55;animation:drift 22s ease-in-out infinite alternate}
55	.orb.a{width:620px;height:620px;background:#0ea5b7;top:-260px;left:-160px}
56	.orb.b{width:560px;height:560px;background:#6d28d9;top:-180px;right:-200px;animation-delay:-8s;opacity:.4}
57	.orb.c{width:480px;height:480px;background:#0369a1;top:55%;left:40%;animation-delay:-14s;opacity:.25}
58	@keyframes drift{to{transform:translate(80px,60px) scale(1.1)}}
59	
60	/* ---------- Nav ---------- */
61	.nav{position:sticky;top:0;z-index:50;transition:background .3s,border-color .3s,backdrop-filter .3s;border-bottom:1px solid transparent}
62	.nav.scrolled{background:rgba(5,11,26,.72);backdrop-filter:blur(16px) saturate(140%);-webkit-backdrop-filter:blur(16px) saturate(140%);border-color:var(--border)}
63	.nav .wrap{display:flex;align-items:center;justify-content:space-between;height:68px}
64	.logo{display:flex;align-items:center;gap:10px;font-weight:700;font-size:19px;letter-spacing:-.02em}
65	.logo-mark{width:32px;height:32px;border-radius:9px;background:linear-gradient(135deg,#0f2147,#0a1532);display:grid;place-items:center;box-shadow:inset 0 0 0 1px var(--border-2),0 0 24px -4px rgba(34,229,200,.5)}
66	.nav-links{display:flex;gap:30px;font-size:14.5px;color:var(--muted)}
67	.nav-links a{transition:color .2s}
68	.nav-links a:hover{color:var(--text)}
69	.nav-cta{display:flex;align-items:center;gap:10px}
70	.menu-btn{display:none;width:40px;height:40px;border-radius:10px;border:1px solid var(--border)}
71	.menu-btn span{display:block;width:18px;height:2px;background:var(--text);margin:4px auto;border-radius:2px;transition:transform .3s,opacity .3s}
72	
73	/* ---------- Buttons ---------- */
74	.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;height:42px;padding:0 18px;border-radius:12px;font-weight:600;font-size:14.5px;transition:transform .2s,box-shadow .2s,background .2s,border-color .2s;white-space:nowrap}
75	.btn-lg{height:52px;padding:0 26px;font-size:16px;border-radius:14px}
76	.btn-primary{background:var(--grad);color:#041022;box-shadow:0 10px 30px -8px rgba(34,229,200,.55),inset 0 1px 0 rgba(255,255,255,.35)}
77	.btn-primary:hover{transform:translateY(-2px);box-shadow:0 18px 40px -10px rgba(56,189,248,.7),inset 0 1px 0 rgba(255,255,255,.35)}
78	.btn-ghost{border:1px solid var(--border-2);background:var(--surface)}
79	.btn-ghost:hover{background:var(--surface-2);border-color:rgba(148,178,255,.35)}
80	.btn .arrow{transition:transform .2s}
81	.btn:hover .arrow{transform:translateX(3px)}
82	
83	/* ---------- Hero ---------- */
84	.hero{padding:72px 0 40px;text-align:center;position:relative}
85	.pill{display:inline-flex;align-items:center;gap:10px;padding:6px 14px 6px 6px;border-radius:999px;border:1px solid var(--border-2);background:rgba(10,20,45,.6);font-size:13.5px;color:var(--muted);backdrop-filter:blur(8px)}
86	.pill b{background:var(--grad);color:#041022;font-size:11.5px;padding:3px 9px;border-radius:999px;letter-spacing:.02em}
87	.pill:hover{color:var(--text)}
88	h1{font-size:clamp(42px,7.4vw,86px);line-height:1.02;letter-spacing:-.045em;font-weight:800;margin:26px auto 22px;max-width:14ch}
89	.grad-text{background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent;background-size:200% 100%;animation:shimmer 8s ease-in-out infinite}
90	@keyframes shimmer{50%{background-position:100% 0}}
91	.lede{font-size:clamp(17px,2vw,20px);color:var(--muted);max-width:620px;margin:0 auto 34px}
92	.hero-ctas{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
93	.hero-note{margin-top:18px;font-size:13.5px;color:var(--dim);display:flex;gap:18px;justify-content:center;flex-wrap:wrap}
94	.hero-note span{display:inline-flex;align-items:center;gap:6px}
95	.hero-note svg{color:var(--teal)}
96	
97	/* ---------- Dashboard mock ---------- */
98	.stage{position:relative;margin:64px auto 0;max-width:1060px;perspective:1800px}
99	.stage::before{content:"";position:absolute;inset:8% 6% -4%;background:var(--grad);filter:blur(80px);opacity:.28;border-radius:40px;z-index:-1}
100	.dash{
101	  border-radius:22px;background:linear-gradient(180deg,rgba(14,26,56,.92),rgba(8,16,38,.95));
102	  box-shadow:var(--shadow),inset 0 1px 0 rgba(255,255,255,.06);
103	  text-align:left;overflow:hidden;transform:rotateX(8deg) scale(.97);transform-origin:50% 0;
104	  transition:transform .9s cubic-bezier(.2,.8,.2,1);
105	}
106	.stage.in .dash{transform:rotateX(0) scale(1)}
107	.dash-top{display:flex;align-items:center;gap:14px;padding:14px 18px;border-bottom:1px solid var(--border)}
108	.dots{display:flex;gap:7px}
109	.dots i{width:11px;height:11px;border-radius:50%;background:#26324f}
110	.dots i:nth-child(1){background:#ff5f57}.dots i:nth-child(2){background:#febc2e}.dots i:nth-child(3){background:#28c840}
111	.url{flex:1;max-width:360px;margin:0 auto;height:28px;border-radius:8px;background:rgba(255,255,255,.04);border:1px solid var(--border);font:12.5px var(--mono);color:var(--dim);display:flex;align-items:center;justify-content:center;gap:6px}
112	.dash-body{display:grid;grid-template-columns:1.55fr 1fr}
113	.dash-main{padding:22px;border-right:1px solid var(--border)}
114	.dash-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;gap:10px;flex-wrap:wrap}
115	.dash-head h3{font-size:15px;font-weight:600;display:flex;align-items:center;gap:10px}
116	.all-good{font-size:12px;font-weight:600;color:var(--green);background:rgba(52,211,153,.1);border:1px solid rgba(52,211,153,.25);padding:3px 10px;border-radius:999px;display:inline-flex;align-items:center;gap:6px}
117	.tabs{display:flex;gap:4px;padding:3px;background:rgba(255,255,255,.04);border-radius:9px;border:1px solid var(--border);font-size:12px}
118	.tabs span{padding:4px 10px;border-radius:6px;color:var(--dim)}
119	.tabs span.on{background:rgba(255,255,255,.08);color:var(--text)}
120	.mon{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,2fr) 64px;align-items:center;gap:16px;padding:12px 4px;border-top:1px solid rgba(148,178,255,.07)}
121	.mon:first-of-type{border-top:0}
122	.mon-name{display:flex;align-items:center;gap:10px;min-width:0}
123	.mon-name div{min-width:0}
124	.mon-name b{font-size:13.5px;font-weight:600;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
125	.mon-name small{font:11.5px var(--mono);color:var(--dim);white-space:nowrap}
126	.status{width:9px;height:9px;border-radius:50%;background:var(--green);flex:none;position:relative}
127	.status::after{content:"";position:absolute;inset:-4px;border-radius:50%;border:2px solid var(--green);opacity:0;animation:ping 2.2s cubic-bezier(0,0,.2,1) infinite}
128	.status.warn{background:var(--amber)}.status.warn::after{border-color:var(--amber)}
129	@keyframes ping{0%{transform:scale(.6);opacity:.8}100%{transform:scale(1.8);opacity:0}}
130	.bars{display:flex;gap:2px;height:26px;align-items:stretch}
131	.bars i{flex:1;border-radius:2px;background:var(--green);opacity:.85;transform-origin:bottom;animation:grow .6s cubic-bezier(.2,.8,.2,1) both}
132	.bars i.w{background:var(--amber)}
133	.bars i.d{background:var(--coral)}
134	.bars i:hover{opacity:1;filter:brightness(1.25)}
135	@keyframes grow{from{transform:scaleY(0)}}
136	.ms{font:600 13px var(--mono);text-align:right;color:var(--text);font-variant-numeric:tabular-nums}
137	.ms small{color:var(--dim);font-weight:400}
138	.dash-side{padding:22px;display:flex;flex-direction:column;gap:16px}
139	.card-mini{border:1px solid var(--border);border-radius:14px;padding:14px;background:rgba(255,255,255,.02)}
140	.card-mini h4{font-size:12px;color:var(--dim);font-weight:500;text-transform:uppercase;letter-spacing:.08em;display:flex;justify-content:space-between}
141	.big{font-size:30px;font-weight:700;letter-spacing:-.03em;margin-top:4px;font-variant-numeric:tabular-nums}
142	.big small{font-size:14px;color:var(--green);font-weight:600;margin-left:6px;letter-spacing:0}
143	#spark{width:100%;height:74px;margin-top:6px}
144	.regions{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:10px}
145	.regions span{font:11px var(--mono);color:var(--muted);background:rgba(255,255,255,.03);border:1px solid var(--border);border-radius:7px;padding:5px 0;text-align:center;position:relative;transition:border-color .3s,color .3s,background .3s}
146	.regions span.hit{border-color:rgba(34,229,200,.6);color:var(--teal);background:rgba(34,229,200,.08)}
147	
148	/* toast */
149	.toast{position:absolute;right:-18px;bottom:-26px;width:320px;border-radius:16px;padding:14px 16px;background:rgba(16,26,52,.92);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);box-shadow:0 20px 50px -10px rgba(0,0,0,.7),0 0 0 1px var(--border-2);text-align:left;display:flex;gap:12px;transform:translateY(20px);opacity:0;transition:transform .5s cubic-bezier(.2,.9,.3,1.3),opacity .4s}
150	.toast.show{transform:none;opacity:1}
151	.toast .ic{width:34px;height:34px;border-radius:10px;flex:none;display:grid;place-items:center;background:rgba(52,211,153,.12);color:var(--green)}
152	.toast.bad .ic{background:rgba(255,107,107,.12);color:var(--coral)}
153	.toast b{font-size:13.5px;display:block}
154	.toast p{font-size:12.5px;color:var(--muted);line-height:1.45}
155	.toast time{font:11px var(--mono);color:var(--dim)}
156	
157	/* ---------- Logos ---------- */
158	.logos{padding:90px 0 30px;text-align:center}
159	.logos p{font-size:13px;color:var(--dim);text-transform:uppercase;letter-spacing:.14em;margin-bottom:26px}
160	.marquee{overflow:hidden;mask-image:linear-gradient(90deg,transparent,#000 12%,#000 88%,transparent);-webkit-mask-image:linear-gradient(90deg,transparent,#000 12%,#000 88%,transparent)}
161	.track{display:flex;gap:64px;width:max-content;animation:scroll 34s linear infinite}
162	.track span{font-size:22px;font-weight:700;color:#55638a;letter-spacing:-.02em;display:flex;align-items:center;gap:8px;white-space:nowrap}
163	.track span:hover{color:var(--muted)}
164	@keyframes scroll{to{transform:translateX(-50%)}}
165	
166	/* ---------- Sections ---------- */
167	section{position:relative}
168	.sec{padding:110px 0}
169	.eyebrow{display:inline-flex;align-items:center;gap:8px;font:600 12.5px var(--mono);color:var(--teal);text-transform:uppercase;letter-spacing:.14em}
170	.eyebrow::before{content:"";width:18px;height:1px;background:currentColor}
171	h2{font-size:clamp(32px,4.6vw,54px);line-height:1.08;letter-spacing:-.035em;font-weight:800;margin:14px 0 16px}
172	.sec-head{max-width:680px;margin-bottom:56px}
173	.sec-head.center{margin-left:auto;margin-right:auto;text-align:center}
174	.sec-head p{color:var(--muted);font-size:18px}
175	
176	/* bento */
177	.bento{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}
178	.tile{grid-column:span 2;position:relative;border-radius:var(--radius);padding:28px;background:linear-gradient(180deg,rgba(255,255,255,.045),rgba(255,255,255,.015));border:1px solid var(--border);overflow:hidden;transition:border-color .3s,transform .3s}
179	.tile::before{content:"";position:absolute;inset:0;border-radius:inherit;background:radial-gradient(420px circle at var(--mx,50%) var(--my,0%),rgba(56,189,248,.14),transparent 45%);opacity:0;transition:opacity .3s;pointer-events:none}
180	.tile:hover{border-color:var(--border-2)}
181	.tile:hover::before{opacity:1}
182	.tile.wide{grid-column:span 3}
183	.tile.xwide{grid-column:span 4}
184	.tile h3{font-size:20px;letter-spacing:-.02em;margin:18px 0 8px}
185	.tile p{color:var(--muted);font-size:15px}
186	.ticon{width:44px;height:44px;border-radius:12px;display:grid;place-items:center;background:rgba(34,229,200,.08);border:1px solid rgba(34,229,200,.22);color:var(--teal)}
187	.ticon.v{background:rgba(139,92,246,.1);border-color:rgba(139,92,246,.3);color:#a78bfa}
188	.ticon.c{background:rgba(56,189,248,.1);border-color:rgba(56,189,248,.3);color:var(--cyan)}
189	.ticon.r{background:rgba(255,107,107,.1);border-color:rgba(255,107,107,.3);color:var(--coral)}
190	
191	/* globe/map viz */
192	.map{margin-top:24px;height:190px;position:relative;border-radius:14px;background:radial-gradient(ellipse at center,rgba(56,189,248,.08),transparent 70%);overflow:hidden}
193	.map svg{width:100%;height:100%}
194	.node{fill:var(--teal)}
195	.node-ring{fill:none;stroke:var(--teal);stroke-width:1.5;transform-box:fill-box;transform-origin:center;animation:ring 2.8s ease-out infinite}
196	@keyframes ring{from{transform:scale(.5);opacity:1}to{transform:scale(3.2);opacity:0}}
197	.arc{fill:none;stroke:url(#arcg);stroke-width:1.5;stroke-dasharray:4 6;animation:dash 1.6s linear infinite}
198	@keyframes dash{to{stroke-dashoffset:-20}}
199	
200	/* alert verify viz */
201	.verify{margin-top:22px;display:flex;flex-direction:column;gap:8px;font:12.5px var(--mono)}
202	.vrow{display:flex;align-items:center;gap:10px;padding:9px 12px;border-radius:10px;background:rgba(255,255,255,.03);border:1px solid var(--border);color:var(--muted)}
203	.vrow .t{margin-left:auto;color:var(--dim)}
204	.chip{font-size:11px;font-weight:700;padding:2px 8px;border-radius:6px}
205	.chip.fail{color:var(--coral);background:rgba(255,107,107,.12)}
206	.chip.ok{color:var(--green);background:rgba(52,211,153,.12)}
207	.chip.go{color:#041022;background:var(--grad)}
208	
209	/* status page mini */
210	.sp{margin-top:22px;border-radius:14px;border:1px solid var(--border);background:#f7f9fc;color:#0b1530;padding:16px;font-size:13px}
211	.sp-h{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}
212	.sp-h b{font-size:14px}
213	.sp-ok{background:#10b981;color:#fff;border-radius:10px;padding:10px 12px;font-weight:600;display:flex;align-items:center;gap:8px;margin-bottom:10px}
214	.sp-row{display:flex;justify-content:space-between;padding:7px 2px;border-top:1px solid #e5e9f2;color:#334155}
215	.sp-row span:last-child{color:#10b981;font-weight:600}
216	
217	/* code */
218	.code{margin-top:22px;border-radius:12px;background:#030817;border:1px solid var(--border);padding:16px;font:12.5px/1.7 var(--mono);color:#c7d2fe;overflow-x:auto;white-space:pre}
219	.code .k{color:#f472b6}.code .s{color:var(--teal)}.code .c{color:#56648a}.code .n{color:var(--amber)}
220	
221	/* integrations */
222	.ints{display:flex;flex-wrap:wrap;gap:8px;margin-top:22px}
223	.ints span{font-size:13px;padding:7px 12px;border-radius:9px;border:1px solid var(--border);background:rgba(255,255,255,.03);color:var(--muted);display:inline-flex;align-items:center;gap:7px}
224	.ints span i{width:8px;height:8px;border-radius:3px;display:inline-block}
225	
226	/* ---------- Steps ---------- */
227	.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;counter-reset:s;position:relative}
228	.steps::before{content:"";position:absolute;top:27px;left:12%;right:12%;height:1px;background:linear-gradient(90deg,transparent,var(--border-2),transparent)}
229	.step{text-align:center;padding:0 10px}
230	.step-n{width:54px;height:54px;margin:0 auto 22px;border-radius:16px;display:grid;place-items:center;font:700 18px var(--mono);background:var(--bg-2);border:1px solid var(--border-2);position:relative;box-shadow:0 0 0 8px var(--bg)}
231	.step-n::after{content:"";position:absolute;inset:-1px;border-radius:inherit;padding:1px;background:var(--grad);-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude}
232	.step h3{font-size:19px;margin-bottom:8px;letter-spacing:-.02em}
233	.step p{color:var(--muted);font-size:15px;max-width:300px;margin:0 auto}
234	
235	/* ---------- Stats ---------- */
236	.stats{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--border);border-radius:22px;background:linear-gradient(180deg,rgba(255,255,255,.04),rgba(255,255,255,.01));overflow:hidden}
237	.stat{padding:38px 28px;border-left:1px solid var(--border)}
238	.stat:first-child{border-left:0}
239	.stat b{display:block;font-size:clamp(32px,4vw,46px);font-weight:800;letter-spacing:-.04em;font-variant-numeric:tabular-nums}
