732	<script>
733	(() => {
734	  const $ = (s, r = document) => r.querySelector(s);
735	  const $$ = (s, r = document) => [...r.querySelectorAll(s)];
736	  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
737	
738	  /* Nav */
739	  const nav = $('#nav'), menuBtn = $('#menuBtn');
740	  const onScroll = () => nav.classList.toggle('scrolled', scrollY > 10);
741	  addEventListener('scroll', onScroll, { passive: true }); onScroll();
742	  menuBtn.addEventListener('click', () => {
743	    const open = nav.classList.toggle('open');
744	    menuBtn.setAttribute('aria-expanded', open);
745	  });
746	  $$('#navLinks a').forEach(a => a.addEventListener('click', () => { nav.classList.remove('open'); menuBtn.setAttribute('aria-expanded', false); }));
747	
748	  /* Monitors */
749	  const monitors = [
750	    { name: 'api.acme.dev', meta: 'HTTPS · 30s', base: 118, warn: [61], down: [] },
751	    { name: 'Checkout service', meta: 'HTTPS · 30s', base: 204, warn: [], down: [] },
752	    { name: 'Realtime websocket', meta: 'TCP · 30s', base: 46, warn: [22, 23], down: [] },
753	    { name: 'Nightly backup', meta: 'Heartbeat · 24h', base: 0, warn: [], down: [74] },
754	    { name: 'Marketing site', meta: 'HTTPS · 60s', base: 88, warn: [], down: [] },
755	  ];
756	  const monEl = $('#monitors');
757	  const BARS = innerWidth < 760 ? 45 : 60;
758	  monitors.forEach((m, i) => {
759	    const row = document.createElement('div');
760	    row.className = 'mon';
761	    let bars = '';
762	    for (let b = 0; b < BARS; b++) {
763	      const idx = Math.round(b * 90 / BARS);
764	      const cls = m.down.some(d => Math.abs(d - idx) < 1.5) ? 'd' : m.warn.some(w => Math.abs(w - idx) < 1.5) ? 'w' : '';
765	      bars += `<i class="${cls}" style="animation-delay:${(i * 60 + b * 8)}ms" title="Day ${idx + 1}"></i>`;
766	    }
767	    row.innerHTML = `
768	      <div class="mon-name"><span class="status"></span><div><b>${m.name}</b><small>${m.meta}</small></div></div>
769	      <div class="bars">${bars}</div>
770	      <div class="ms" data-i="${i}">${m.base ? m.base + '<small>ms</small>' : '<small>OK</small>'}</div>`;
771	    monEl.appendChild(row);
772	  });
773	
774	  /* Live sparkline */
775	  const N = 40, pts = [];
776	  for (let i = 0; i < N; i++) pts.push(130 + Math.sin(i / 3) * 18 + Math.random() * 22);
777	  const line = $('#sparkLine'), area = $('#sparkArea'), dot = $('#sparkDot'), avg = $('#avgMs');
778	  function drawSpark() {
779	    const W = 300, H = 74, min = 90, max = 200;
780	    const xy = pts.map((v, i) => [i * W / (N - 1), H - 6 - (v - min) / (max - min) * (H - 14)]);
781	    let d = `M${xy[0][0]},${xy[0][1]}`;
782	    for (let i = 1; i < xy.length; i++) {
783	      const [x0, y0] = xy[i - 1], [x1, y1] = xy[i], cx = (x0 + x1) / 2;
784	      d += ` C${cx},${y0} ${cx},${y1} ${x1},${y1}`;
785	    }
786	    line.setAttribute('d', d);
787	    area.setAttribute('d', d + ` L${W},${H} L0,${H} Z`);
788	    const last = xy[xy.length - 1];
789	    dot.setAttribute('cx', last[0] - 2); dot.setAttribute('cy', last[1]);
790	    const a = Math.round(pts.slice(-8).reduce((s, v) => s + v, 0) / 8);
791	    avg.textContent = a;
792	  }
793	  drawSpark();
794	
795	  /* Region probe cycling */
796	  const regions = $$('#regions span');
797	  let rIdx = 0;
798	
799	  function tick() {
800	    pts.shift(); pts.push(120 + Math.sin(Date.now() / 2400) * 18 + Math.random() * 28);
801	    drawSpark();
802	    $$('.ms[data-i]').forEach(el => {
803	      const m = monitors[+el.dataset.i];
804	      if (!m.base) return;
805	      const v = Math.max(12, Math.round(m.base + (Math.random() - .5) * m.base * .35));
806	      el.innerHTML = v + '<small>ms</small>';
807	    });
808	    regions.forEach(r => r.classList.remove('hit'));
809	    regions[rIdx % regions.length].classList.add('hit');
810	    regions[(rIdx + 3) % regions.length].classList.add('hit');
811	    rIdx++;
812	  }
813	  if (!reduce) setInterval(tick, 1400);
814	
815	  /* Toast cycle */
816	  const toasts = [
817	    { bad: true, t: 'Checkout service is slow', p: 'p95 at 1.8s from fra, lhr. Confirmed in 3 of 3 regions. Paged @maya.', time: 'just now · #incidents' },
818	    { bad: false, t: 'Resolved: Checkout service', p: 'Back to normal after 4m 12s. Status page updated automatically.', time: 'just now · #incidents' },
819	    { bad: false, t: 'SSL renews in 14 days', p: 'api.acme.dev certificate expires Nov 21. We\'ll remind you again at 3 days.', time: '2m ago · email' },
820	  ];
821	  const toast = $('#toast'); let tI = 0;
822	  const icBad = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M12 9v4M12 17h.01"/><path d="M10.3 3.9L1.8 18a2 2 0 001.7 3h17a2 2 0 001.7-3L13.7 3.9a2 2 0 00-3.4 0z"/></svg>';
823	  const icOk = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6"><path d="M5 12l5 5L20 7"/></svg>';
824	  function showToast() {
825	    const d = toasts[tI++ % toasts.length];
826	    toast.classList.remove('show');
827	    setTimeout(() => {
828	      toast.classList.toggle('bad', d.bad);
829	      $('#toastIc').innerHTML = d.bad ? icBad : icOk;
830	      $('#toastT').textContent = d.t; $('#toastP').textContent = d.p; $('#toastTime').textContent = d.time;
831	      toast.classList.add('show');
832	    }, 450);
833	  }
834	
835	  /* Map nodes */
836	  const nodes = [[95,62],[60,70],[165,145],[300,50],[315,58],[310,120],[400,70],[455,62],[490,85],[510,140],[430,95],[140,52]];
837	  const gN = $('#nodes'), gA = $('#arcs'), NS = 'http://www.w3.org/2000/svg';
838	  const hub = [300, 50];
839	  nodes.forEach(([x, y], i) => {
840	    if (i !== 3) {
841	      const p = document.createElementNS(NS, 'path');
842	      const mx = (x + hub[0]) / 2, my = Math.min(y, hub[1]) - 30 - Math.abs(x - hub[0]) * .12;
843	      p.setAttribute('d', `M${hub[0]},${hub[1]} Q${mx},${my} ${x},${y}`);
844	      p.setAttribute('class', 'arc'); p.style.animationDelay = (i * -.2) + 's';
845	      gA.appendChild(p);
846	    }
847	    const ring = document.createElementNS(NS, 'circle');
848	    ring.setAttribute('cx', x); ring.setAttribute('cy', y); ring.setAttribute('r', 4);
849	    ring.setAttribute('class', 'node-ring'); ring.style.animationDelay = (i * .23) + 's';
850	    const c = document.createElementNS(NS, 'circle');
851	    c.setAttribute('cx', x); c.setAttribute('cy', y); c.setAttribute('r', 3.5); c.setAttribute('class', 'node');
852	    gN.append(ring, c);
853	  });
854	
855	  /* Reveal + stage + counters */
856	  const counted = new WeakSet();
857	  function count(el) {
858	    if (counted.has(el)) return; counted.add(el);
859	    const to = parseFloat(el.dataset.to), dec = +(el.dataset.dec || 0), dur = 1600, t0 = performance.now();
860	    const step = now => {
861	      const k = Math.min(1, (now - t0) / dur), e = 1 - Math.pow(1 - k, 3);
862	      el.textContent = (to * e).toFixed(dec);
863	      if (k < 1) requestAnimationFrame(step);
864	    };
865	    reduce ? (el.textContent = to.toFixed(dec)) : requestAnimationFrame(step);
866	  }
867	  const io = new IntersectionObserver(entries => {
868	    entries.forEach(en => {
869	      if (!en.isIntersecting) return;
870	      en.target.classList.add('in');
871	      $$('.count', en.target).forEach(count);
872	      if (en.target.id === 'stage' && !toast.dataset.started) {
873	        toast.dataset.started = 1;
874	        setTimeout(showToast, 900);
875	        if (!reduce) setInterval(showToast, 5200);
876	      }
877	      io.unobserve(en.target);
878	    });
879	  }, { threshold: .15, rootMargin: '0px 0px -40px 0px' });
880	  $$('.reveal, #stage').forEach(el => io.observe(el));
881	
882	  /* Spotlight on tiles */
883	  $$('.tile').forEach(t => t.addEventListener('pointermove', e => {
884	    const r = t.getBoundingClientRect();
885	    t.style.setProperty('--mx', (e.clientX - r.left) + 'px');
886	    t.style.setProperty('--my', (e.clientY - r.top) + 'px');
887	  }));
888	
889	  /* Dashboard tilt on pointer */
890	  const stage = $('#stage'), dash = $('.dash');
891	  if (!reduce && matchMedia('(pointer:fine)').matches) {
892	    stage.addEventListener('pointermove', e => {
893	      if (!stage.classList.contains('in')) return;
894	      const r = stage.getBoundingClientRect();
895	      const x = (e.clientX - r.left) / r.width - .5, y = (e.clientY - r.top) / r.height - .5;
896	      dash.style.transition = 'transform .15s ease-out';
897	      dash.style.transform = `rotateY(${x * 4}deg) rotateX(${-y * 4}deg)`;
898	    });
899	    stage.addEventListener('pointerleave', () => { dash.style.transition = 'transform .6s ease'; dash.style.transform = ''; });
900	  }
901	
902	  /* Marquee: duplicate items for seamless loop */
903	  const track = $('#track'); track.innerHTML += track.innerHTML;
904	  [...track.children].slice(track.children.length / 2).forEach(c => c.setAttribute('aria-hidden', 'true'));
905	
906	  /* Pricing toggle */
907	  const billing = $('#billing'), knob = $('#knob'), btns = $$('button', billing);
908	  function setKnob(b) { knob.style.width = b.offsetWidth + 'px'; knob.style.transform = `translateX(${b.offsetLeft - 4}px)`; }
909	  btns.forEach(b => b.addEventListener('click', () => {
910	    btns.forEach(x => { x.classList.toggle('on', x === b); x.setAttribute('aria-pressed', x === b); });
911	    setKnob(b);
912	    const p = b.dataset.period;
913	    $$('.amt').forEach(a => {
914	      const target = +a.dataset[p], from = +a.textContent, t0 = performance.now();
915	      const step = now => { const k = Math.min(1, (now - t0) / 400); a.textContent = Math.round(from + (target - from) * k); if (k < 1) requestAnimationFrame(step); };
916	      requestAnimationFrame(step);
917	    });
918	  }));
919	  const syncKnob = () => setKnob($('button.on', billing));
920	  addEventListener('resize', syncKnob); requestAnimationFrame(syncKnob);
921	  if (document.fonts && document.fonts.ready) document.fonts.ready.then(syncKnob);
922	
923	  /* Signup */
924	  $('#signup').addEventListener('submit', e => {
925	    e.preventDefault();
926	    const v = $('#email').value.trim(), msg = $('#signupMsg');
927	    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) { msg.style.color = 'var(--coral)'; msg.textContent = 'Enter a valid work email to get started.'; return; }
928	    msg.style.color = 'var(--teal)';
929	    msg.textContent = `You're in. We sent a setup link to ${v}.`;
930	    $('#email').value = '';
931	  });
932	})();
933	</script>
934	</body>
935	</html>
