*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{
  font-family:var(--font);background:var(--bg);color:var(--text);
  line-height:1.6;overflow-x:hidden;-webkit-font-smoothing:antialiased;
}
a{color:inherit;text-decoration:none}
button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}
img,svg{display:block}
.wrap{max-width:1180px;margin:0 auto;padding:0 24px}
::selection{background:rgba(34,229,200,.35)}
:focus-visible{outline:2px solid var(--teal);outline-offset:3px;border-radius:8px}

/* ---------- Background ---------- */
.bg-fx{position:fixed;inset:0;z-index:-1;pointer-events:none;overflow:hidden}
.bg-fx::before{
  content:"";position:absolute;inset:0;
  background-image:linear-gradient(rgba(148,178,255,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(148,178,255,.05) 1px,transparent 1px);
  background-size:56px 56px;
  mask-image:radial-gradient(ellipse 80% 60% at 50% 0%,#000 30%,transparent 75%);
  -webkit-mask-image:radial-gradient(ellipse 80% 60% at 50% 0%,#000 30%,transparent 75%);
}
.orb{position:absolute;border-radius:50%;filter:blur(90px);opacity:.55}
.orb.a{width:620px;height:620px;background:#0ea5b7;top:-260px;left:-160px}
.orb.b{width:560px;height:560px;background:#6d28d9;top:-180px;right:-200px;animation-delay:-8s;opacity:.4}
.orb.c{width:480px;height:480px;background:#0369a1;top:55%;left:40%;animation-delay:-14s;opacity:.25}
