590	
591	<footer>
592	  <div class="wrap">
593	    <div class="foot">
594	      <div>
595	        <a href="#" class="logo"><span class="logo-mark"><svg width="20" height="20" viewBox="0 0 24 24" fill="none"><path d="M2 14c2.6 0 2.6-3 5.2-3s2.6 3 5.2 3 2.6-3 5.2-3S20.2 14 22 14" stroke="#22e5c8" stroke-width="2.6" stroke-linecap="round"/></svg></span>Tideline</a>
596	        <p style="margin-top:14px;max-width:300px">Calm, reliable uptime monitoring for small engineering teams.</p>
597	        <span class="sys"><span class="status" style="width:7px;height:7px"></span>All Tideline systems operational</span>
598	      </div>
599	      <div><h5>Product</h5><ul><li><a href="#features">Features</a></li><li><a href="#pricing">Pricing</a></li><li><a href="#">Status pages</a></li><li><a href="#">Changelog</a></li></ul></div>
600	      <div><h5>Developers</h5><ul><li><a href="#">Docs</a></li><li><a href="#">API reference</a></li><li><a href="#">CLI</a></li><li><a href="#">Terraform</a></li></ul></div>
601	      <div><h5>Company</h5><ul><li><a href="#">About</a></li><li><a href="#">Blog</a></li><li><a href="#">Careers</a></li><li><a href="#">Contact</a></li></ul></div>
602	    </div>
603	    <div class="foot-bottom"><span>© Tideline Labs, Inc.</span><span><a href="#">Privacy</a> · <a href="#">Terms</a> · <a href="#">Security</a></span></div>
604	  </div>
605	</footer>
606	
607	<script>
608	(() => {
609	  const $ = (s, r = document) => r.querySelector(s);
610	  const $$ = (s, r = document) => [...r.querySelectorAll(s)];
611	  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
612	
613	  /* Nav */
614	  const nav = $('#nav'), menuBtn = $('#menuBtn');
615	  const onScroll = () => nav.classList.toggle('scrolled', scrollY > 10);
616	  addEventListener('scroll', onScroll, { passive: true }); onScroll();
617	  menuBtn.addEventListener('click', () => {
618	    const open = nav.classList.toggle('open');
619	    menuBtn.setAttribute('aria-expanded', open);
620	  });
621	  $$('#navLinks a').forEach(a => a.addEventListener('click', () => { nav.classList.remove('open'); menuBtn.setAttribute('aria-expanded', false); }));
622	
623	  /* Monitors */
624	  const monitors = [
625	    { name: 'api.acme.dev', meta: 'HTTPS · 30s', base: 118, warn: [61], down: [] },
626	    { name: 'Checkout service', meta: 'HTTPS · 30s', base: 204, warn: [], down: [] },
627	    { name: 'Realtime websocket', meta: 'TCP · 30s', base: 46, warn: [22, 23], down: [] },
628	    { name: 'Nightly backup', meta: 'Heartbeat · 24h', base: 0, warn: [], down: [74] },
629	    { name: 'Marketing site', meta: 'HTTPS · 60s', base: 88, warn: [], down: [] },
630	  ];
631	  const monEl = $('#monitors');
632	  const BARS = innerWidth < 760 ? 45 : 60;
633	  monitors.forEach((m, i) => {
634	    const row = document.createElement('div');
635	    row.className = 'mon';
636	    let bars = '';
637	    for (let b = 0; b < BARS; b++) {
638	      const idx = Math.round(b * 90 / BARS);
639	      const cls = m.down.some(d => Math.abs(d - idx) < 1.5) ? 'd' : m.warn.some(w => Math.abs(w - idx) < 1.5) ? 'w' : '';
640	      bars += `<i class="${cls}" style="animation-delay:${(i * 60 + b * 8)}ms" title="Day ${idx + 1}"></i>`;
641	    }
642	    row.innerHTML = `
643	      <div class="mon-name"><span class="status"></span><div><b>${m.name}</b><small>${m.meta}</small></div></div>
644	      <div class="bars">${bars}</div>
645	      <div class="ms" data-i="${i}">${m.base ? m.base + '<small>ms</small>' : '<small>OK</small>'}</div>`;
646	    monEl.appendChild(row);
647	  });
648	
649	  /* Live sparkline */
650	  const N = 40, pts = [];
651	  for (let i = 0; i < N; i++) pts.push(130 + Math.sin(i / 3) * 18 + Math.random() * 22);
652	  const line = $('#sparkLine'), area = $('#sparkArea'), dot = $('#sparkDot'), avg = $('#avgMs');
653	  function drawSpark() {
654	    const W = 300, H = 74, min = 90, max = 200;
655	    const xy = pts.map((v, i) => [i * W / (N - 1), H - 6 - (v - min) / (max - min) * (H - 14)]);
656	    let d = `M${xy[0][0]},${xy[0][1]}`;
657	    for (let i = 1; i < xy.length; i++) {
658	      const [x0, y0] = xy[i - 1], [x1, y1] = xy[i], cx = (x0 + x1) / 2;
659	      d += ` C${cx},${y0} ${cx},${y1} ${x1},${y1}`;
660	    }
661	    line.setAttribute('d', d);
662	    area.setAttribute('d', d + ` L${W},${H} L0,${H} Z`);
663	    const last = xy[xy.length - 1];
664	    dot.setAttribute('cx', last[0] - 2); dot.setAttribute('cy', last[1]);
665	    const a = Math.round(pts.slice(-8).reduce((s, v) => s + v, 0) / 8);
666	    avg.textContent = a;
667	  }
668	  drawSpark();
669	
670	  /* Region probe cycling */
671	  const regions = $$('#regions span');
672	  let rIdx = 0;
673	
674	  function tick() {
675	    pts.shift(); pts.push(120 + Math.sin(Date.now() / 2400) * 18 + Math.random() * 28);
676	    drawSpark();
677	    $$('.ms[data-i]').forEach(el => {
678	      const m = monitors[+el.dataset.i];
679	      if (!m.base) return;
680	      const v = Math.max(12, Math.round(m.base + (Math.random() - .5) * m.base * .35));
681	      el.innerHTML = v + '<small>ms</small>';
682	    });
683	    regions.forEach(r => r.classList.remove('hit'));
684	    regions[rIdx % regions.length].classList.add('hit');
685	    regions[(rIdx + 3) % regions.length].classList.add('hit');
686	    rIdx++;
687	  }
688	  tick();
689	
690	  /* Toast cycle */
691	  const toasts = [
692	    { bad: true, t: 'Checkout service is slow', p: 'p95 at 1.8s from fra, lhr. Confirmed in 3 of 3 regions. Paged @maya.', time: 'just now · #incidents' },
693	    { bad: false, t: 'Resolved: Checkout service', p: 'Back to normal after 4m 12s. Status page updated automatically.', time: 'just now · #incidents' },
694	    { bad: false, t: 'SSL renews in 14 days', p: 'api.acme.dev certificate expires Nov 21. We\'ll remind you again at 3 days.', time: '2m ago · email' },
695	  ];
696	  const toast = $('#toast'); let tI = 0;
697	  const icBad = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M12 9v4M12 17h.01"/><path d="M10.3 3.9L1.8 18a2 2 0 001.7 3h17a2 2 0 001.7-3L13.7 3.9a2 2 0 00-3.4 0z"/></svg>';
698	  const icOk = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6"><path d="M5 12l5 5L20 7"/></svg>';
699	  function showToast() {
700	    const d = toasts[tI++ % toasts.length];
701	    toast.classList.remove('show');
702	    setTimeout(() => {
703	      toast.classList.toggle('bad', d.bad);
704	      $('#toastIc').innerHTML = d.bad ? icBad : icOk;
705	      $('#toastT').textContent = d.t; $('#toastP').textContent = d.p; $('#toastTime').textContent = d.time;
706	      toast.classList.add('show');
707	    }, 450);
708	  }
709	
710	  /* Map nodes */
711	  const nodes = [[95,62],[60,70],[165,145],[300,50],[315,58],[310,120],[400,70],[455,62],[490,85],[510,140],[430,95],[140,52]];
712	  const gN = $('#nodes'), gA = $('#arcs'), NS = 'http://www.w3.org/2000/svg';
713	  const hub = [300, 50];
714	  nodes.forEach(([x, y], i) => {
715	    if (i !== 3) {
716	      const p = document.createElementNS(NS, 'path');
717	      const mx = (x + hub[0]) / 2, my = Math.min(y, hub[1]) - 30 - Math.abs(x - hub[0]) * .12;
718	      p.setAttribute('d', `M${hub[0]},${hub[1]} Q${mx},${my} ${x},${y}`);
719	      p.setAttribute('class', 'arc'); p.style.animationDelay = (i * -.2) + 's';
720	      gA.appendChild(p);
721	    }
722	    const ring = document.createElementNS(NS, 'circle');
723	    ring.setAttribute('cx', x); ring.setAttribute('cy', y); ring.setAttribute('r', 4);
724	    ring.setAttribute('class', 'node-ring'); ring.style.animationDelay = (i * .23) + 's';
725	    const c = document.createElementNS(NS, 'circle');
726	    c.setAttribute('cx', x); c.setAttribute('cy', y); c.setAttribute('r', 3.5); c.setAttribute('class', 'node');
727	    gN.append(ring, c);
728	  });
729	
730	  /* Reveal + stage + counters */
731	  const counted = new WeakSet();
732	  function count(el) {
733	    if (counted.has(el)) return; counted.add(el);
734	    const to = parseFloat(el.dataset.to), dec = +(el.dataset.dec || 0), dur = 1600, t0 = performance.now();
735	    const step = now => {
736	      const k = Math.min(1, (now - t0) / dur), e = 1 - Math.pow(1 - k, 3);
737	      el.textContent = (to * e).toFixed(dec);
738	      if (k < 1) requestAnimationFrame(step);
739	    };
740	    reduce ? (el.textContent = to.toFixed(dec)) : requestAnimationFrame(step);
741	  }
742	  const io = new IntersectionObserver(entries => {
743	    entries.forEach(en => {
744	      if (!en.isIntersecting) return;
745	      en.target.classList.add('in');
746	      $$('.count', en.target).forEach(count);
747	      if (en.target.id === 'stage' && !toast.dataset.started) {
748	        toast.dataset.started = 1;
749	        setTimeout(showToast, 900);
750	      }
751	      io.unobserve(en.target);
752	    });
753	  }, { threshold: .15, rootMargin: '0px 0px -40px 0px' });
754	  $$('.reveal, #stage').forEach(el => io.observe(el));
755	
756	  /* Spotlight on tiles */
757	  $$('.tile').forEach(t => t.addEventListener('pointermove', e => {
758	    const r = t.getBoundingClientRect();
759	    t.style.setProperty('--mx', (e.clientX - r.left) + 'px');
760	    t.style.setProperty('--my', (e.clientY - r.top) + 'px');
761	  }));
762	
763	  /* Dashboard tilt on pointer */
764	  const stage = $('#stage'), dash = $('.dash');
765	  if (!reduce && matchMedia('(pointer:fine)').matches) {
766	    stage.addEventListener('pointermove', e => {
767	      if (!stage.classList.contains('in')) return;
768	      const r = stage.getBoundingClientRect();
769	      const x = (e.clientX - r.left) / r.width - .5, y = (e.clientY - r.top) / r.height - .5;
770	      dash.style.transition = 'transform .15s ease-out';
771	      dash.style.transform = `rotateY(${x * 4}deg) rotateX(${-y * 4}deg)`;
772	    });
773	    stage.addEventListener('pointerleave', () => { dash.style.transition = 'transform .6s ease'; dash.style.transform = ''; });
774	  }
775	
776	  /* Pricing toggle */
777	  const billing = $('#billing'), knob = $('#knob'), btns = $$('button', billing);
778	  function setKnob(b) { knob.style.width = b.offsetWidth + 'px'; knob.style.transform = `translateX(${b.offsetLeft - 4}px)`; }
779	  btns.forEach(b => b.addEventListener('click', () => {
780	    btns.forEach(x => { x.classList.toggle('on', x === b); x.setAttribute('aria-pressed', x === b); });
781	    setKnob(b);
782	    const p = b.dataset.period;
783	    $$('.amt').forEach(a => {
784	      const target = +a.dataset[p], from = +a.textContent, t0 = performance.now();
785	      const step = now => { const k = Math.min(1, (now - t0) / 400); a.textContent = Math.round(from + (target - from) * k); if (k < 1) requestAnimationFrame(step); };
786	      requestAnimationFrame(step);
787	    });
788	  }));
789	  const syncKnob = () => setKnob($('button.on', billing));
790	  addEventListener('resize', syncKnob); requestAnimationFrame(syncKnob);
791	  if (document.fonts && document.fonts.ready) document.fonts.ready.then(syncKnob);
792	
793	  /* Signup */
794	  $('#signup').addEventListener('submit', e => {
795	    e.preventDefault();
796	    const v = $('#email').value.trim(), msg = $('#signupMsg');
797	    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) { msg.style.color = 'var(--coral)'; msg.textContent = 'Enter a valid work email to get started.'; return; }
798	    msg.style.color = 'var(--teal)';
799	    msg.textContent = `You're in. We sent a setup link to ${v}.`;
800	    $('#email').value = '';
801	  });
802	})();
803	</script>
804	</body>
805	</html>
