/* Pricing toggle */
const billing = $('#billing'), knob = $('#knob'), btns = $$('button', billing);
function setKnob(b) { knob.style.width = b.offsetWidth + 'px'; knob.style.transform = `translateX(${b.offsetLeft - 4}px)`; }
btns.forEach(b => b.addEventListener('click', () => {
  btns.forEach(x => { x.classList.toggle('on', x === b); x.setAttribute('aria-pressed', x === b); });
  setKnob(b);
  const p = b.dataset.period;
  $$('.amt').forEach(a => {
    const target = +a.dataset[p], from = +a.textContent, t0 = performance.now();
    const step = now => { const k = Math.min(1, (now - t0) / 400); a.textContent = Math.round(from + (target - from) * k); if (k < 1) requestAnimationFrame(step); };
    requestAnimationFrame(step);
  });
}));
const syncKnob = () => setKnob($('button.on', billing));
addEventListener('resize', syncKnob); requestAnimationFrame(syncKnob);
if (document.fonts && document.fonts.ready) document.fonts.ready.then(syncKnob);

